    tier smallint NOT NULL,
    periods_paid integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    paid_until timestamp with time zone NOT NULL,
    grace_until timestamp with time zone,
    state text DEFAULT 'active'::text NOT NULL,
    ended_at timestamp with time zone,
    end_reason text,
    club_id uuid,
    slot text GENERATED ALWAYS AS (
CASE kind
    WHEN 'stall'::text THEN 'stall'::text
    WHEN 'club_room'::text THEN 'club'::text
    ELSE 'home'::text
END) STORED,
    CONSTRAINT leases_kind_check CHECK ((kind = ANY (ARRAY['home'::text, 'apartment'::text, 'stall'::text, 'club_room'::text]))),
    CONSTRAINT leases_state_check CHECK ((state = ANY (ARRAY['active'::text, 'grace'::text, 'ended'::text])))
);


